// Путь к вспомогательному node-скрипту записи истории/метрик (dist/core/record-history.js).
const require = createRequire(import.meta.url);
const resolvedRecorder = require.resolve("./core/record-history.js");
// Д6: ворота выгрузки. После dispose новые in-process запуски отклоняются,
// а начатые — получают время завершить запись в БД.
const shutdownGate = createShutdownGate();
const SHUTDOWN_WAIT_MS = 15000;
/**
 * Плагин может загружаться как из dist, так и напрямую из src (tsx/транспиляция).
 * Node не умеет исполнять .ts, поэтому для фоновых задач всегда берём
 * скомпилированный dist/core/record-history.js.
 */
const recorderPath = (() => {
    if (!resolvedRecorder.endsWith(".ts"))
        return resolvedRecorder;
    const distPath = resolvedRecorder
        .replace(/([\\/])src([\\/])/, "$1dist$2")
        .replace(/\.ts$/, ".js");
    if (existsSync(distPath))
        return distPath;
    console.warn("[agent-steward] Не найден собранный record-history.js: " +
        `${distPath}. История/метрики не будут записываться. Выполните npm run build.`);
    return distPath;
})();
/**
 * Путь к гейту расписания (dist/core/schedule-gate.js). Обёртка запускает его
 * перед opencode и выходит, если cron не сработал или запуск перенесён.
 */
const gatePath = (() => {
    const resolved = require.resolve("./core/schedule-gate.js");
    if (!resolved.endsWith(".ts"))
        return resolved;
    const distPath = resolved
        .replace(/([\\/])src([\\/])/, "$1dist$2")
        .replace(/\.ts$/, ".js");
    if (existsSync(distPath))
        return distPath;
    console.warn("[agent-steward] Не найден собранный schedule-gate.js: " +
        `${distPath}. Гейт расписания не будет проверяться. Выполните npm run build.`);
    return distPath;
})();
/** Бэкенд планировщика текущей ОС (schtasks / crontab / launchd). */
const scheduler = getSchedulerBackend();
/** Per-workspace overrides for matrix clones (Sprint 17). */
export const matrixOverrideSchema = z.object({
    prompt: z.string().optional(),
    model: z.string().optional(),
    qualityGate: z.string().optional(),
    beforeScript: z.string().optional(),
    afterScript: z.string().optional(),
});
/** Matrix (fan-out) configuration. */
export const matrixSchema = z.object({
    workspaceIds: z
        .array(z.string())
        .describe("Workspace ids to fan out to. Cannot be combined with workspaceId."),
    strategy: z
        .enum(["parallel", "sequential"])
        .optional()
        .describe("parallel (default) starts all clones at once; sequential starts the next clone only after the previous one finishes."),
    failureMode: z
        .enum(["continue", "stop"])
        .optional()
        .describe("continue (default) keeps running the remaining clones after a failure; stop aborts the rest."),
    aggregation: z
        .enum(["summary", "per-task"])
        .optional()
        .describe("summary (default) writes one aggregate record for the parent; per-task keeps per-clone records."),
    createAggregator: z
        .boolean()
        .optional()
        .describe("Also create the <parent>-matrix-complete task depending on every clone."),
    concurrency: z
        .number()
        .optional()
        .describe("Maximum number of clones running at the same time (>= 1). Ignored for sequential (always 1) and capped by the global maxConcurrent setting."),
    overrides: z
        .record(z.string(), matrixOverrideSchema)
        .optional()
        .describe("Per-workspace overrides keyed by workspace id. Keys must be present in workspaceIds."),
});
/** Zod-схема аргументов schedule_task */
export const scheduleTaskSchema = z.object({
    name: z
        .string()
        .describe("Unique task name (the plugin prefix is applied automatically). Allowed: letters (including Cyrillic), digits, space, dot, underscore and hyphen."),
    schedule: z
        .string()
        .optional()
        .describe("Cron expression (5 fields: minute hour day-of-month month day-of-week). Required for triggerType=cron; ignored for file/mcp-event. Supports ranges, lists, */N steps, month/weekday names, @every 15m|2h|1d, L (last day of month) and FRI#3 (third Friday). Expressions schtasks cannot express are checked every minute inside the wrapper."),
    runAt: z
        .string()
        .optional()
        .describe("Absolute one-shot start time in ISO-8601 (e.g. 2026-12-01T09:00:00Z). Requires triggerType=once; mutually exclusive with delaySeconds (runAt wins)."),
    delaySeconds: z
        .number()
        .int()
        .positive()
        .optional()
        .describe("One-shot delay in seconds from now. Requires triggerType=once. Convenient alternative to runAt."),
    session: z
        .enum(["new", "reuse", "last"])
        .optional()
        .describe("OpenCode session mode for the task: new (default, fresh session per run), reuse (keep a persistent session stored on the task — sessionId is auto-generated), last (continue the latest session via --continue)."),
    sessionMaxRuns: z
        .number()
        .int()
        .min(0)
        .max(10000)
        .optional()
        .describe("Only for session=reuse: how many runs the reused session survives before it is deleted and a fresh one is created. Unset/0 — no limit."),
    timezone: z
        .string()
        .optional()
        .describe("IANA timezone of the schedule, e.g. Europe/Moscow. Defaults to the system timezone. A zone different from the system one is evaluated by the wrapper (poll mode)."),
    notBefore: z
        .string()
        .optional()
        .describe("Launch window start in HH:MM (24h). Together with notAfter: a run outside the window is postponed to the next window opening, not skipped."),
    notAfter: z
        .string()
        .optional()
        .describe("Launch window end in HH:MM (24h). May be earlier than notBefore (window crosses midnight)."),
    prompt: z
        .string()
        .describe("Prompt passed to the agent on every run."),
    timeoutSeconds: z
        .number()
        .optional()
        .describe("Run timeout in seconds (default 3600)."),
    model: z
        .string()
        .optional()
        .describe("LLM model in OpenCode format, e.g. anthropic/claude-3-5-sonnet. Defaults to the OpenCode default model."),
    priority: z
        .number()
        .optional()
        .describe("Task priority 0..10 (10 is the highest). Default 5 (normal)."),
    beforeScript: z
        .string()
        .optional()
        .describe("Pre-flight shell command executed before the run (e.g. git pull). A non-zero exit code cancels the run."),
    afterScript: z
        .string()
        .optional()
        .describe("Post-flight shell command executed after the run (e.g. git push). Runs even when the task fails."),
    qualityGate: z
        .string()
        .optional()
        .describe("Shell command executed after a successful AI response (e.g. npm test). A non-zero exit code marks the run as a Quality Gate failure."),
    dependsOn: z
        .array(z.string())
        .optional()
        .describe("DAG dependencies: tasks that must finish successfully before this task starts."),
    retryCount: z
        .number()
        .optional()
        .describe("How many times to retry a failed run (default 0)."),
    retryDelay: z
        .number()
        .optional()
        .describe("Delay between retries in seconds (default 60)."),
    nextTaskOnSuccess: z
        .string()
        .optional()
        .describe("Task started after a successful run."),
    nextTaskOnError: z
        .string()
        .optional()
        .describe("Compensation/rollback task started after a failed run."),
    triggerType: z
        .enum(["cron", "file", "git", "mcp-event", "once"])
        .optional()
        .describe("Trigger type: cron (default), file, git (new commits in the task working directory), mcp-event or once (single run at runAt/delaySeconds)."),
    mcpEvent: z
        .object({
        server: z.string(),
        event: z.string(),
        filter: z.string().optional(),
    })
        .optional()
        .describe("MCP event trigger: server, event name and an optional filter (key=value or regex)."),
    watchPath: z
        .string()
        .optional()
        .describe("File or directory to watch when triggerType is \"file\". Can be set here or later via update_task."),
    watchGlobs: z
        .array(z.string())
        .optional()
        .describe("Glob masks that limit a file trigger, e.g. [\"**/*.md\", \"src/**\"]. Empty means any change under watchPath."),
    watchIgnore: z
        .array(z.string())
        .optional()
        .describe("Glob masks excluded from a file trigger, e.g. [\"node_modules/**\", \"*.log\"]. Supports leading ! to re-include."),
    gitBranch: z
        .string()
        .optional()
        .describe("Only for triggerType=git: branch name or glob (main, release/*, comma-separated). Empty means any branch."),
    gitPaths: z
        .array(z.string())
        .optional()
        .describe("Only for triggerType=git: glob masks of changed files that must match to start the task (git diff --name-only)."),
    gitIgnore: z
        .array(z.string())
        .optional()
        .describe("Only for triggerType=git: glob masks of changed files to ignore."),
    gitPollSeconds: z
        .number()
        .int()
        .min(5)
        .optional()
        .describe("Only for triggerType=git: polling interval in seconds (default 60, minimum 5)."),
    activeDays: z
        .array(z.number().int().min(0).max(6))
        .optional()
        .describe("Allowed weekdays 0=Sunday..6=Saturday for cron and event triggers. Empty or all seven means every day."),
    windowPolicy: z
        .enum(["skip", "postpone", "run"])
        .optional()
        .describe("Behaviour outside the launch window / active days: postpone (default, wait for the next opening), skip or run anyway."),
    workingDirectory: z
        .string()
        .optional()
        .describe("Working directory of the task. Defaults to the current project folder so opencode run picks up the project's opencode.json with MCP servers."),
    workspaceId: z
        .string()
        .optional()
        .describe("Multi-repo workspace binding. When set, cwd = workspace path and workingDirectory is ignored."),
    allowedTools: z
        .array(z.string())
        .optional()
        .describe("Role-scoped tool allow-list, enforced through OPENCODE_CONFIG_CONTENT. A non-empty list also allows actions that the default policy denies (for example shell). An empty array is rejected."),
    deniedTools: z
        .array(z.string())
        .optional()
        .describe("Role-scoped tool deny-list (takes precedence over allowedTools and over the default policy). Enforced through OPENCODE_CONFIG_CONTENT."),
    legacyShell: z
        .boolean()
        .optional()
        .describe("Transitional flag (release 1.6): under the hybrid policy, re-enable shell for this task. Prefer listing shell in allowedTools. Ignored by secure/legacy policy."),
    runWhenLoggedOff: z
        .boolean()
        .optional()
        .describe("Windows only: run the task even when no user is logged on (/ru SYSTEM). The task runs in session 0 without the user's profile, mapped drives or saved credentials, so tasks that need the user's environment may fail. Creating such a task usually requires an elevated shell. Default false: interactive only �
